function exIndex(){return Math.max(0,languageOptions.findIndex(x=>x[0]===lang()))}
function ex(key,vars={}){let text=experienceCopy[key]?.[exIndex()]||key;for(const [k,v] of Object.entries(vars))text=text.replaceAll('{'+k+'}',String(v));return text}
uiMap.set('Temalar',experienceCopy.themes);
const themeOptions=[{id:'violet',bg:'#111111',end:'#141229',button:'#5045E8',accent:'#FFD600'},{id:'emerald',bg:'#F8F4E9',end:'#E9F0E6',button:'#064E3B',accent:'#A78416'},{id:'ocean',bg:'#07151F',end:'#102C3C',button:'#116A80',accent:'#87E4E8'},{id:'rose',bg:'#22151E',end:'#3C2033',button:'#925074',accent:'#F5C9A3'}];
function selectedTheme(){const t=read('basira-theme','violet');return themeOptions.some(x=>x.id===t)?t:'violet'}
function applyTheme(id=selectedTheme()){const theme=themeOptions.find(x=>x.id===id)||themeOptions[0];document.documentElement.dataset.theme=theme.id;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme.bg}
function chooseTheme(id){if(!themeOptions.some(x=>x.id===id))return;save('basira-theme',id);applyTheme(id);document.querySelectorAll('[data-theme-choice]').forEach(b=>{const yes=b.dataset.themeChoice===id;b.setAttribute('aria-pressed',yes);b.querySelector('.theme-check').textContent=yes?'✓':'○'});}
function themeCards(){return `<div class="theme-grid">${themeOptions.map(t=>`<button type="button" class="theme-choice" data-theme-choice="${t.id}" aria-pressed="${selectedTheme()===t.id}" onclick="chooseTheme('${t.id}')"><span class="theme-sample" style="--sample-bg:${t.bg};--sample-end:${t.end};--sample-btn:${t.button};--sample-accent:${t.accent}"><span class="sample-moon">☾</span><i></i><i></i><b></b></span><span class="theme-name">${ex(t.id)}<span class="theme-check">${selectedTheme()===t.id?'✓':'○'}</span></span></button>`).join('')}</div>`}
function themesPage(){return head(ex('themes'),'')+`<section class="themes-page"><p class="muted">${ex('themeBody')}</p>${themeCards()}</section>`}
function personalProfile(){const p=read('basira-profile',{});return {...p,name:typeof p.name==='string'?p.name.slice(0,40):'',closeness:Math.min(100,Math.max(0,Number(p.closeness)||0))}}
let onboarding=null,typeTimer=null,prepTimer=null,typingState=null,keyboardAudio=null,lastTypeTick=0;
const onboardingSteps=['welcome','source','story','name','intro','purpose','journey','heart','prepare','theme'];
function persistOnboarding(){if(!onboarding)return;save('basira-profile',onboarding.profile);save('basira-onboarding',{version:1,step:onboarding.step,complete:false});}
function openOnboarding(restart=false){if(onboarding)return;const saved=read('basira-onboarding',{});if(!restart&&saved.complete)return;onboarding={step:restart?0:Math.max(0,Math.min(9,Number(saved.step)||0)),profile:personalProfile(),prepared:false};document.querySelector('#welcome')?.remove();const el=document.createElement('section');el.id='onboarding';el.setAttribute('role','dialog');el.setAttribute('aria-modal','true');el.setAttribute('aria-labelledby','onboardingTitle');document.body.appendChild(el);document.querySelector('main').inert=true;document.querySelector('#bottomNav').inert=true;document.body.classList.add('is-onboarding');persistOnboarding();renderOnboarding();}
function closeOnboarding(){clearTimeout(typeTimer);clearTimeout(prepTimer);save('basira-profile',onboarding.profile);save('basira-onboarding',{version:1,step:9,complete:true});save('nur-started',true);onboarding=null;document.querySelector('#onboarding')?.remove();document.querySelector('main').inert=false;document.querySelector('#bottomNav').inert=false;document.body.classList.remove('is-onboarding');go('home');render();}
function obBack(){if(!onboarding||!onboarding.step)return;onboarding.step--;persistOnboarding();renderOnboarding();}
function obNext(skip=false){if(!onboarding)return;enableTypingAudio();const step=onboardingSteps[onboarding.step];if(typingState&&!typingState.done){finishTyping();return}if(step==='source'&&!skip&&!onboarding.profile.source)return;if(step==='name'){const input=document.querySelector('#personalName');const name=(input?.value||'').trim().replace(/[\u0000-\u001f\u007f]/g,'').slice(0,40);if(!name){input?.focus();return}onboarding.profile.name=name;input?.blur()}if(step==='purpose'&&!onboarding.profile.purpose)return;if(step==='journey'&&!onboarding.profile.journey)return;if(step==='prepare'&&!onboarding.prepared)return;if(step==='theme'){closeOnboarding();return}onboarding.step++;persistOnboarding();renderOnboarding();}
function obSelect(field,value){onboarding.profile[field]=value;persistOnboarding();document.querySelectorAll('[data-answer]').forEach(b=>{const yes=b.dataset.answer===value;b.setAttribute('aria-pressed',yes);b.querySelector('.choice-check').textContent=yes?'✓':'○'});document.querySelector('#obContinue').disabled=false;const note=document.querySelector('#lockNote');if(note)note.hidden=value!=='lock';if(read('basira-intro-haptic',true)&&navigator.vibrate)try{navigator.vibrate(12)}catch{}}
function obChoices(field,choices){return `<div class="ob-choices">${choices.map(([id,label,icon])=>`<button class="ob-choice" type="button" data-answer="${id}" aria-pressed="${onboarding.profile[field]===id}" onclick="obSelect('${field}','${id}')"><span class="choice-icon">${icon}</span><span>${label}</span><span class="choice-check">${onboarding.profile[field]===id?'✓':'○'}</span></button>`).join('')}</div>`}
function setCloseness(value){if(!onboarding)return;const n=Math.min(100,Math.max(0,Math.round(Number(value))));onboarding.profile.closeness=n;persistOnboarding();const svg=document.querySelector('#heartFill');svg?.style.setProperty('--heart-fill',(100-n)+'%');const percent=document.querySelector('#heartPercent');if(percent)percent.textContent=n+'%';const label=document.querySelector('#heartLabel');if(label)label.textContent=experienceCopy.heartLabels[exIndex()][Math.min(4,Math.floor(n/25))];}
function toggleIntroEffect(key){save('basira-intro-'+key,!read('basira-intro-'+key,true));const btn=document.querySelector('#intro-'+key);btn?.setAttribute('aria-pressed',read('basira-intro-'+key,true));if(key==='sound')enableTypingAudio();}
function enableTypingAudio(){if(!read('basira-intro-sound',true))return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!keyboardAudio)keyboardAudio=new Audio();if(keyboardAudio.state==='suspended')keyboardAudio.resume().catch(()=>{})}catch{}}
function typingFeedback(){const now=Date.now();if(now-lastTypeTick<95)return;lastTypeTick=now;if(read('basira-intro-sound',true)&&keyboardAudio?.state==='running'){try{const o=keyboardAudio.createOscillator(),g=keyboardAudio.createGain();o.type='triangle';o.frequency.setValueAtTime(750+Math.random()*230,keyboardAudio.currentTime);g.gain.setValueAtTime(.018,keyboardAudio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,keyboardAudio.currentTime+.018);o.connect(g);g.connect(keyboardAudio.destination);o.start();o.stop(keyboardAudio.currentTime+.02)}catch{}}if(read('basira-intro-haptic',true)&&navigator.vibrate)try{navigator.vibrate(6)}catch{}}
function typeStory(text){const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;typingState={chars:Array.from(text),at:0,speed:1,done:false};const tick=()=>{if(!onboarding||!typingState)return;const el=document.querySelector('#typedStory');if(!el)return;typingState.at=Math.min(typingState.chars.length,typingState.at+typingState.speed);el.textContent=typingState.chars.slice(0,typingState.at).join('');if(typingState.at<typingState.chars.length){typingFeedback();typeTimer=setTimeout(tick,27)}else{typingState.done=true;el.classList.add('type-done')}};if(reduced)finishTyping();else tick()}
function finishTyping(){clearTimeout(typeTimer);if(!typingState)return;typingState.done=true;const el=document.querySelector('#typedStory');if(el){el.textContent=typingState.chars.join('');el.classList.add('type-done')}}
function speedTyping(){enableTypingAudio();if(!typingState||typingState.done)return;if(typingState.speed===1)typingState.speed=5;else finishTyping()}
function renderOnboarding(){clearTimeout(typeTimer);clearTimeout(prepTimer);typingState=null;const step=onboardingSteps[onboarding.step],p=onboarding.profile,n=p.name||'',vars={name:n};let title='',sub='',content='',typed='',disabled=false,button=ex('next');
 if(step==='welcome'){title=ex('welcome');sub=ex('welcomeBody');button=ex('start');content=`<div class="ob-brand-hero">${shamsLogo('welcome-mark')}<p>${ex('tagline')}</p></div>`}
 if(step==='source'){title=ex('sourceTitle');sub=ex('sourceBody');content=obChoices('source',[['friends',ex('friends'),'♡'],...['Instagram','TikTok','Facebook','Threads','YouTube','App Store','Google'].map((s,i)=>[s,s,['◎','♪','f','@','▷','A','G'][i]]),['other',ex('other'),'•••']]);disabled=!p.source}
 if(step==='story'){title=ex('storyTitle');typed=ex('story');content='<div class="ob-breath"><span>✦</span></div>'}
 if(step==='name'){title=ex('nameTitle');sub=ex('nameBody');content=`<form class="ob-name-form" onsubmit="event.preventDefault();obNext()"><label for="personalName">${ex('nameLabel')}</label><input id="personalName" name="given-name" autocomplete="given-name" enterkeyhint="next" maxlength="40" value="${esc(n)}" placeholder="${ex('nameLabel')}" oninput="document.querySelector('#obContinue').disabled=!this.value.trim()"><p class="ob-fine">⌑ ${ex('nameHint')}</p></form>`;disabled=!n}
 if(step==='intro'){title=ex('meet',vars);typed=ex('intro');content='<span class="ob-mini-emblem">✧</span>'}
 if(step==='purpose'){title=ex('purposeTitle');sub=ex('purposeBody');content=obChoices('purpose',[['faith',ex('faith'),'✧'],['peace',ex('peace'),'☾'],['inspiration',ex('inspiration'),'☀'],['reading',ex('reading'),'▥'],['lock',ex('lock'),'▯']])+`<p id="lockNote" class="ob-fine" ${p.purpose==='lock'?'':'hidden'}>${ex('lockNote')}</p>`;disabled=!p.purpose}
 if(step==='journey'){title=ex('journeyTitle');sub=ex('journeyBody');content=obChoices('journey',[['exploring',ex('exploring'),'✧'],['returning',ex('returning'),'↗'],['growing',ex('growing'),'❋'],['devoted',ex('devoted'),'✦']]);disabled=!p.journey}
 if(step==='heart'){title=ex('heartTitle');sub=ex('heartBody');content=`<div class="heart-widget"><svg id="heartFill" viewBox="0 0 200 180" style="--heart-fill:${100-p.closeness}%" aria-hidden="true"><defs><clipPath id="heartClip"><path d="M100 163C85 150 15 103 15 59C15 14 69 3 100 41C131 3 185 14 185 59C185 103 115 150 100 163Z"/></clipPath></defs><path class="heart-outline" d="M100 163C85 150 15 103 15 59C15 14 69 3 100 41C131 3 185 14 185 59C185 103 115 150 100 163Z"/><g clip-path="url(#heartClip)"><g class="heart-liquid"><rect x="0" y="0" width="200" height="180"/><path d="M-200 3Q-150 -10 -100 3T0 3T100 3T200 3T300 3T400 3V25H-200Z"/></g></g></svg><strong id="heartPercent">${p.closeness}%</strong><p id="heartLabel">${experienceCopy.heartLabels[exIndex()][Math.min(4,Math.floor(p.closeness/25))]}</p><input type="range" min="0" max="100" step="1" value="${p.closeness}" aria-label="${ex('heartTitle')}" oninput="setCloseness(this.value)"><div class="range-labels"><span>0%</span><span>100%</span></div></div>`}
 if(step==='prepare'){title=ex('beginning',vars);content=`<div class="ob-verse"><span class="ob-mini-emblem">✧</span><p class="arabic" lang="ar" dir="rtl">أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ</p><p>${ex('verse')}</p><a href="https://quran.com/13/28" target="_blank" rel="noopener">${ex('verseRef')} ↗</a></div><div class="ob-preparation"><div class="prep-caption"><span id="prepMessage" role="status">${ex('preparing')}</span><b id="prepPercent">0%</b></div><div class="prep-track" role="progressbar" aria-label="${ex('preparing')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span id="prepFill"></span></div></div>`;disabled=true}
 if(step==='theme'){title=ex('themeTitle');sub=ex('themeBody');content=themeCards();button=ex('enter')}
 const personal=['purpose','journey','heart'].includes(step)?`<p class="ob-person-name">${esc(n)} <span>✦</span></p>`:'';
 document.querySelector('#onboarding').innerHTML=`<div class="ob-shell" data-step="${step}" data-localized="true"><div class="ob-top"><button class="ob-back" aria-label="${ex('back')}" onclick="obBack()" ${!onboarding.step?'disabled':''}>‹</button><span class="ob-small-brand">${shamsLogo()}</span><span class="ob-step">${String(onboarding.step+1).padStart(2,'0')} <span>/ 10</span></span></div><div class="ob-step-track"><span style="width:${(onboarding.step+1)*10}%"></span></div><div class="ob-content">${step==='welcome'?content:''}${personal}<h1 id="onboardingTitle" tabindex="-1">${esc(title)}</h1>${sub?`<p class="ob-subtitle">${sub}</p>`:''}${step!=='welcome'?content:''}${typed?`<button class="type-panel" aria-label="${ex('speedHint')}" onclick="speedTyping()"><span class="type-screenreader">${esc(typed)}</span><span id="typedStory" aria-hidden="true"></span></button><p class="type-hint">${ex('speedHint')} ↗</p>`:''}</div><div class="ob-bottom"><button id="obContinue" class="ob-primary" onclick="obNext()" ${disabled?'disabled':''}><span>${button}</span><span>→</span></button>${step==='source'?`<button class="ob-skip" onclick="obNext(true)">${ex('skip')}</button>`:''}<div class="ob-dots" aria-hidden="true">${onboardingSteps.map((_,i)=>`<i class="${i===onboarding.step?'current':i<onboarding.step?'done':''}"></i>`).join('')}</div></div></div>`;
 document.querySelector('#onboardingTitle')?.focus({preventScroll:true});
 if(typed)typeStory(typed);
 if(step==='prepare'){onboarding.prepared=false;const start=Date.now();const tick=()=>{if(!onboarding||onboardingSteps[onboarding.step]!=='prepare')return;const pct=Math.min(100,Math.round((Date.now()-start)/28));document.querySelector('#prepFill').style.width=pct+'%';document.querySelector('#prepPercent').textContent=pct+'%';document.querySelector('.prep-track').setAttribute('aria-valuenow',pct);if(pct<100)prepTimer=setTimeout(tick,40);else{onboarding.prepared=true;document.querySelector('#prepMessage').textContent=ex('ready');document.querySelector('#obContinue').disabled=false}};tick()}
}
function initializeExperience(){applyTheme();if(!read('basira-onboarding',{}).complete)openOnboarding();document.addEventListener('keydown',event=>{if(!onboarding||event.key!=='Tab')return;const focusable=[...document.querySelectorAll('#onboarding button:not(:disabled),#onboarding input,#onboarding a[href]')].filter(x=>x.offsetParent!==null),first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}});}
